export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"ideas-for-practicing-observing-by-coming-back-to-your-senses-remember-observing-b04ed81c9f77\",\"title\":\"Ideas for Practicing Observing By Coming Back to Your Senses Remember: Observing is bringing your mind back to the sensations of your body and mind. Observe with your eyes:\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9939,0.7885,0.8935,0.7928,0.8881],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/02-dbt-mindfulness-mindfulness-handout-4a-ideas-for-practicing-observing-by-coming-back-to-y-d9d2cdb2ef.json\",\"sha256\":\"d9d2cdb2ef29dd93d311f9b3e8d647cbbd439246e3d1ee05c2f1c4a0e2736774\",\"domain\":\"dbt\",\"bytes\":26439},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/mindfulness-handout-4a-ideas-for-practicing-observing-by-coming-back-to-your-senses-remember-6d4de2287a.json\",\"sha256\":\"6d4de2287aba6cfbf576280ffa5c883e3cc1989e4247a87faaf5fadd99b7f46b\",\"domain\":\"dbt\",\"bytes\":26286},{\"sourcePath\":\"skills/skills/d012.json\",\"sha256\":\"ae6624e95569d0c3cddbc7348a27aa198e6ab10b8f36e13028399b4a3abd6253\",\"domain\":\"dbt\",\"bytes\":30579},{\"sourcePath\":\"skills/skills/dbt/02_dbt_mindfulness_mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_y_91ad10e2.json\",\"sha256\":\"2c33f42866ea838d6885ae6bbe6895201651c49603dccc085704117818cc6473\",\"domain\":\"dbt\",\"bytes\":29402}]},\"data\":{\"pages\":[{\"pdf_page\":78,\"book_page\":\"54\",\"text\":\"54\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nMindfulness Handout 4a   (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\\nIdeas for Practicing Observing\\nBy Coming Back to Your Senses\\nRemember: Observing is bringing your mind back to the sensations of your body and mind.\\nObserve with your eyes:\\n  1.\\t\uf071\\tLie on the ground and watch the clouds in the sky.\\n  2.\\t\uf071\\tWalking slowly, stopping somewhere with a view, notice flowers, trees, and nature itself.\\n  3.\\t\uf071\\tSit outside. Watch who and what go by in front of you, without following them with your\\nhead or your eyes.\\n  4.\\t\uf071\\tNotice the facial expression and movements of another person. Refrain from labeling the\\nperson\u2019s emotions, thoughts, or interests.\\n  5.\\t\uf071\\tNotice just the eyes, lips, or hands of another person (or just one feature of an animal).\\n  6.\\t\uf071\\tPick up a leaf, a flower, or a pebble. Look at it closely, trying to see each detail.\\n  7.\\t \uf071\\tFind something beautiful to look at, and spend a few minutes contemplating it.\\n  8.\\tOther:\\nObserve sounds:\\n  9.\\t\uf071\\tStop for a moment and just listen. Listen to the texture and shape of the sounds around\\nyou. Listen to the silences between the sounds.\\n10.\\t\uf071\\tIf someone is talking, listen to the pitch of the voice, to the smoothness or roughness of the\\nsounds, to the clarity or the mumbling of the speech, to the pauses between the words.\\n11.\\t \uf071\\tListen to music, observing each note as it comes and the spaces between the notes. Try\\nbreathing the sounds into your body and letting them flow out again on your out breath.\\n12.\\tOther:\\nObserve smells around you:\\n13.\\t\uf071\\tBreathing in, notice any smells around you. Bring something close to your nose, and notice\\nthe smells. Take it away, and then notice the smells again. Do they linger?\\n14.\\t\uf071\\tWhen eating, notice the aroma of the food; when cooking, notice the aroma of the spices or\\nother ingredients; when bathing, smell the soap or shampoo; when walking outside, notice\\nthe aroma of the air; when near flowers, bend down and \u201csmell the roses.\u201d\\n15.\\tOther:\\nObserve taste and the act of eating:\\n16.\\t\uf071\\tPutting something in your mouth, pay attention to the taste. Keep it in your mouth, and\\nnotice all the taste sensations.\\n17.\\t \uf071\\tLick a lollipop or something else. Notice just the sensation of taste.\\n18.\\t\uf071\\tEat a meal, or even a part of a meal, paying attention to the taste of each mouthful.\\n19.\\tOther:\\nObserve urges to do something:\\nWhen you are feeling an urge to do something impulsive,\\n20.\\t\uf071\\t\u201cUrge-surf\u201d by imagining that your urges are a surfboard and you are standing on the\\nboard, riding the waves.\\n21.\\t\uf071\\tNotice any urge to avoid someone or something.\\n22.\\t\uf071\\tScan your entire body, and notice the sensations. Where in the body is the urge?\\n23.\\t\uf071\\tWhen you are chewing your food, notice when you have the urge to swallow.\\n24.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":79,\"book_page\":\"55\",\"text\":\"55\\nMindfulness Handout 4a   (p. 2 of 4)\\nObserve sensations of touch on your skin:\\n25.\\t\uf071\\tStroke your upper lip with your fingernail.\\n\u2022\u2022 Stop stroking, and notice how long it takes before you can\u2019t sense your upper lip at all.\\n26.\\t\uf071\\tWhen walking, notice the sensations of walking\u2014your feet hitting the ground and rising up\\nand down. Sometimes walk very slowly and notice. Sometimes walk very fast and notice.\\n27.\\t \uf071\\tWhen sitting, notice your thighs on the chair. Notice the curve of your knees and your back.\\n28.\\t\uf071\\tPay attention to anything touching you.\\n\u2022\u2022 Try to feel your feet in your shoes, your body touching your clothes.\\n\u2022\u2022 Feel your arms touching a chair.\\n\u2022\u2022 Notice the sensations of your hands.\\n29.\\t\uf071\\tTouch something\u2014the wall, a fabric, a table top, a pet, a piece of fruit, a person.\\n\u2022\u2022 Notice the texture of what you feel, notice the sensations on your skin.\\n\u2022\u2022 Try it again with another part of your body.\\n\u2022\u2022 Notice the sensations again.\\n30.\\t\uf071\\tFocus your attention on the sensations in your chest, your stomach, or your shoulders.\\n31.\\t\uf071\\tFocus your attention on the place in your body where you feel tight or tense.\\n32.\\t\uf071\\tFocus your attention on the space between your eyes.\\n33.\\tOther:\\nObserve your breath: Breathe evenly and gently, focusing your attention on:\\n34.\\t\uf071\\tThe movement of your stomach.\\n\u2022\u2022 As you begin to breathe in, allow your belly to rise in order to bring air into the lower half\\nof your lungs.\\n\u2022\u2022 As the upper halves of your lungs begin to fill with air, your chest begins to rise.\\n\u2022\u2022 As you breathe out, notice your belly, then notice your chest. Don\u2019t tire yourself.\\n35.\\t\uf071\\tThe pauses in your breathing.\\n\u2022\u2022 As you breathe in, notice the brief pause when your lungs have filled with air.\\n\u2022\u2022 As you breathe out, notice the brief pause when you have expelled all the air.\\n36.\\t\uf071\\tThe sensations in your nose as you breathe in and as you breathe out.\\n\u2022\u2022 As you breathe, close your mouth and breathe in through your nose, noticing the\\nsensations traveling up and down your nostrils.\\n37.\\t \uf071\\tYour breath while walking slowly. Breathe normally.\\n\u2022\u2022 Determine the length of your breath\u2014the exhalation and the inhalation\u2014by the number\\nof your footsteps. Continue for a few minutes.\\n\u2022\u2022 Begin to lengthen your exhalation by one step. Do not force a longer inhalation. Let it be\\nnatural.\\n\u2022\u2022 Watch your inhalation carefully to see whether there is a desire to lengthen it. Now\\nlengthen the exhalation by one more footstep.\\n\u2022\u2022 Watch to see whether the inhalation also lengthens by one step or not.\\n\u2022\u2022 Only lengthen the inhalation when you feel that it will be comfortable.\\n\u2022\u2022 After 20 breaths, return your breath to normal.\\n38.\\t\uf071\\tYour breath while listening to a piece of music.\\n\u2022\u2022 Breathe long, light, and even breaths.\\n\u2022\u2022 Follow your breath; be master of it, while remaining aware of the movement and\\nsentiments of the music.\\n\u2022\u2022 Do not get lost in the music, but continue to be master of your breath and yourself.\\n39.\\t\uf071\\tYour breath while listening to a friend\u2019s words and your own replies. Continue as with music.\\n40.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":80,\"book_page\":\"56\",\"text\":\"56\\nMindfulness Handout 4a   (p. 3 of 4)\\nObserve thoughts coming in and out of your mind:\\n41.\\t \uf071\\tNotice thoughts as they come into your mind.\\n\u2022\u2022 Ask, \u201cWhere do thoughts come from?\u201d\\n\u2022\u2022 Then watch them to see if you can see where they come into your mind.\\n42.\\t\uf071\\tAs you notice thoughts in your mind, notice the pauses between each thought.\\n43.\\t\uf071\\tImagine that your mind is the sky and that thoughts are clouds.\\n\u2022\u2022 Notice each thought-cloud as it drifts by, letting it drift in and out of your mind.\\n\u2022\u2022 Imagine thoughts as leaves on water flowing down a stream, as boats drifting by on the\\nlake, or as train cars rolling by you.\\n44.\\t\uf071\\tWhen worries go round and round in your mind, move your attention to the sensations\\nin your body (those most intense right now). Then, keeping your attention on your body\\nsensations, notice how long it takes for the worries to ooze away.\\n45.\\t\uf071\\tStep back from your mind, as if you are on top of a mountain and your mind is just a\\nboulder down below.\\n\u2022\u2022 Gaze at your mind, watching what thoughts come up when you are watching it.\\n\u2022\u2022 Come back into your mind before you stop.\\n46.\\t\uf071\\tWatch for the first two thoughts that come into your mind.\\n47.\\t Other:\\nImagine that your mind is a:\\n48.\\t\uf071\\tConveyor belt, and that thoughts and feelings are coming down the belt.\\n\u2022\u2022 Put each thought or feeling in a box, and then put it on the conveyor belt and let it go by.\\n49.\\t\uf071\\tConveyor belt, and that you are sorting thoughts and feelings as they come down the belt.\\n\u2022\u2022 Label the types of thoughts or feelings coming by (e.g., worry thoughts, thoughts about\\nmy past, thoughts about my mother, planning-what-to-do thoughts, angry feeling, sad\\nfeelings).\\n\u2022\u2022 Put them in boxes nearby for another time.\\n50.\\t\uf071\\tRiver, and that thoughts and feelings are boats going down the river.\\n\u2022\u2022 Imagine sitting on the grass, watching the boats go by.\\n\u2022\u2022 Describe or label each boat as it goes by.\\n\u2022\u2022 Try not to jump on the boat.\\n51.\\t \uf071\\tRailroad track, and that thoughts and feelings are train cars going by.\\n\u2022\u2022 Describe or label each as it goes by. Try not to jump on the train.\\n52.\\tOther:\\nObserve by expanding awareness:\\n53.\\t\uf071\\tBreathing in, notice your breath. Then, keeping your breath in your awareness, on the\\nnext breath notice your hands. Then, keeping both in your awareness, on the next breath\\nexpand your awareness to sounds.\\n\u2022\u2022 Continue holding all three in awareness at the same time.\\n\u2022\u2022 Practice this awareness of threes at other times, selecting other things to be aware of.\\n54.\\t\uf071\\tKeeping your focus on what you are currently doing, gently expand your awareness to\\ninclude the space around you.\\n55.\\t\uf071\\tGo hug a tree, and feel the sensations of the embrace.\\n\u2022\u2022 Attend to the embrace of the sheets and blankets or comforters around you as you lie in\\nbed.\\n\u2022\u2022 Do this when you feel lonely and want to be loved or to love.\\n56.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":81,\"book_page\":\"57\",\"text\":\"57\\nMindfulness Handout 4a   (p. 4 of 4)\\nOpen your mind to your senses:\\n57.\\t \uf071\\tPractice walking with your senses as wide open as you can make them.\\n\u2022\u2022 Notice what you hear, see, and feel.\\n\u2022\u2022 Notice what you feel when shifting your weight between each step.\\n\u2022\u2022 Notice your body experience as you turn.\\n58.\\t\uf071\\tFor one mouthful in a meal, pause with a spoonful or forkful of food.\\n\u2022\u2022 Look at what you are going to eat, smell it, and listen to it. Then, when you are ready, put\\nit in your mouth.\\n\u2022\u2022 Note the taste, texture, temperature, and even the sound your teeth make in chewing your\\nmouthful slowly.\\n\u2022\u2022 Note the changes in its taste, texture, temperature, and sound as you chew it to\\ncompletion.\\n59.\\t\uf071\\tFocus your mind on paying attention to each sensation that comes into your mind.\\n\u2022\u2022 Attend to sensations of sight, smell, touch, hearing, and taste, or to the thoughts\\ngenerated by your brain.\\n\u2022\u2022 Notice sensations as they arise, and notice them as they fall away.\\n\u2022\u2022 Let your mind focus on each sensation as it arises.\\n\u2022\u2022 Notice each sensation with curiosity, allowing it to be. Examine the uniqueness of each\\nsensation.\\n60.\\t\uf071\\tBe here. Be in the present now.\\n\u2022\u2022 Take a moment to notice every sense you are aware of.\\n\u2022\u2022 To yourself, make a statement, about each sense: \u201cI feel the chair; the chair feels me.\u201d\\n\u201cI hear the heater; the heater hears me.\u201d \u201cI see the wall; the wall sees me.\u201d \u201cI hear a\\nstomach growl; it hears me.\u201d\\n61.\\t\uf071\\tWhen a feeling arises within you, notice it\u2014saying, for example, \u201cA feeling of sadness is\\narising within me.\u201d\\n62.\\t\uf071\\tWhen a thought arises within you, notice it\u2014saying, for example, \u201cThe thought \u2018It is hot in\\nhere\u2019 is arising within me.\u201d\\n63.\\t\uf071\\tTake just a moment of your time, and practice \u201cnothing-to-do\u201d mind.\\n\u2022\u2022 Let yourself become completely aware of your present experience, noticing sensations\\nand the space around you.\\n64.\\t\uf071\\tFind a small object, one you can hold in your hand. Place it in front of you on a table or in\\nyour lap. Observe it closely\u2014first not moving it, and then picking it up and turning it over\\nand around, gazing at it from different angles and in different lights. Just notice shapes,\\ncolors, sizes, and other characteristics that are visible.\\n\u2022\u2022 Then change your focus to your fingers and hands touching the object. Notice the\\nsensations of touching the object; notice the texture, temperature, and feel of the object.\\n\u2022\u2022 Put the object down. Close your eyes, and inhale and exhale deeply and slowly.\\n\u2022\u2022 Then, with beginner\u2019s mind, open your eyes. With new vision, once again notice the\\nobject. With beginner\u2019s mind, open to feeling new textures and sensations, explore the\\nobject with your fingers and hands.\\n\u2022\u2022 Put down the object, and once again focus your mind on inhaling and exhaling once.\\n65.\\tOther:\"},{\"pdf_page\":78,\"book_page\":\"54\",\"text\":\"54\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nMindfulness Handout 4a (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\\nIdeas for Practicing Observing\\nBy Coming Back to Your Senses\\nRemember: Observing is bringing your mind back to the sensations of your body and mind.\\nObserve with your eyes: 1.\\t\uf071\\tLie on the ground and watch the clouds in the sky. 2.\\t\uf071\\tWalking slowly, stopping somewhere with a view, notice flowers, trees, and nature itself. 3.\\t\uf071\\tSit outside. Watch who and what go by in front of you, without following them with your\\nhead or your eyes. 4.\\t\uf071\\tNotice the facial expression and movements of another person. Refrain from labeling the\\nperson\u2019s emotions, thoughts, or interests. 5.\\t\uf071\\tNotice just the eyes, lips, or hands of another person (or just one feature of an animal). 6.\\t\uf071\\tPick up a leaf, a flower, or a pebble. Look at it closely, trying to see each detail. 7. \uf071\\tFind something beautiful to look at, and spend a few minutes contemplating it. 8.\\tOther:\\nObserve sounds: 9.\\t\uf071\\tStop for a moment and just listen. Listen to the texture and shape of the sounds around\\nyou. Listen to the silences between the sounds.\\n10.\\t\uf071\\tIf someone is talking, listen to the pitch of the voice, to the smoothness or roughness of the\\nsounds, to the clarity or the mumbling of the speech, to the pauses between the words.\\n11. \uf071\\tListen to music, observing each note as it comes and the spaces between the notes. Try\\nbreathing the sounds into your body and letting them flow out again on your out breath.\\n12.\\tOther:\\nObserve smells around you:\\n13.\\t\uf071\\tBreathing in, notice any smells around you. Bring something close to your nose, and notice\\nthe smells. Take it away, and then notice the smells again. Do they linger?\\n14.\\t\uf071\\tWhen eating, notice the aroma of the food; when cooking, notice the aroma of the spices or\\nother ingredients; when bathing, smell the soap or shampoo; when walking outside, notice\\nthe aroma of the air; when near flowers, bend down and \u201csmell the roses.\u201d\\n15.\\tOther:\\nObserve taste and the act of eating:\\n16.\\t\uf071\\tPutting something in your mouth, pay attention to the taste. Keep it in your mouth, and\\nnotice all the taste sensations.\\n17. \uf071\\tLick a lollipop or something else. Notice just the sensation of taste.\\n18.\\t\uf071\\tEat a meal, or even a part of a meal, paying attention to the taste of each mouthful.\\n19.\\tOther:\\nObserve urges to do something:\\nWhen you are feeling an urge to do something impulsive,\\n20.\\t\uf071\\t\u201cUrge-surf\u201d by imagining that your urges are a surfboard and you are standing on the\\nboard, riding the waves.\\n21.\\t\uf071\\tNotice any urge to avoid someone or something.\\n22.\\t\uf071\\tScan your entire body, and notice the sensations. Where in the body is the urge?\\n23.\\t\uf071\\tWhen you are chewing your food, notice when you have the urge to swallow.\\n24.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":79,\"book_page\":\"55\",\"text\":\"55\\nMindfulness Handout 4a (p. 2 of 4)\\nObserve sensations of touch on your skin:\\n25.\\t\uf071\\tStroke your upper lip with your fingernail.\\n\u2022\u2022 Stop stroking, and notice how long it takes before you can\u2019t sense your upper lip at all.\\n26.\\t\uf071\\tWhen walking, notice the sensations of walking\u2014your feet hitting the ground and rising up\\nand down. Sometimes walk very slowly and notice. Sometimes walk very fast and notice.\\n27. \uf071\\tWhen sitting, notice your thighs on the chair. Notice the curve of your knees and your back.\\n28.\\t\uf071\\tPay attention to anything touching you.\\n\u2022\u2022 Try to feel your feet in your shoes, your body touching your clothes.\\n\u2022\u2022 Feel your arms touching a chair.\\n\u2022\u2022 Notice the sensations of your hands.\\n29.\\t\uf071\\tTouch something\u2014the wall, a fabric, a table top, a pet, a piece of fruit, a person.\\n\u2022\u2022 Notice the texture of what you feel, notice the sensations on your skin.\\n\u2022\u2022 Try it again with another part of your body.\\n\u2022\u2022 Notice the sensations again.\\n30.\\t\uf071\\tFocus your attention on the sensations in your chest, your stomach, or your shoulders.\\n31.\\t\uf071\\tFocus your attention on the place in your body where you feel tight or tense.\\n32.\\t\uf071\\tFocus your attention on the space between your eyes.\\n33.\\tOther:\\nObserve your breath: Breathe evenly and gently, focusing your attention on:\\n34.\\t\uf071\\tThe movement of your stomach.\\n\u2022\u2022 As you begin to breathe in, allow your belly to rise in order to bring air into the lower half\\nof your lungs.\\n\u2022\u2022 As the upper halves of your lungs begin to fill with air, your chest begins to rise.\\n\u2022\u2022 As you breathe out, notice your belly, then notice your chest. Don\u2019t tire yourself.\\n35.\\t\uf071\\tThe pauses in your breathing.\\n\u2022\u2022 As you breathe in, notice the brief pause when your lungs have filled with air.\\n\u2022\u2022 As you breathe out, notice the brief pause when you have expelled all the air.\\n36.\\t\uf071\\tThe sensations in your nose as you breathe in and as you breathe out.\\n\u2022\u2022 As you breathe, close your mouth and breathe in through your nose, noticing the\\nsensations traveling up and down your nostrils.\\n37. \uf071\\tYour breath while walking slowly. Breathe normally.\\n\u2022\u2022 Determine the length of your breath\u2014the exhalation and the inhalation\u2014by the number\\nof your footsteps. Continue for a few minutes.\\n\u2022\u2022 Begin to lengthen your exhalation by one step. Do not force a longer inhalation. Let it be\\nnatural.\\n\u2022\u2022 Watch your inhalation carefully to see whether there is a desire to lengthen it. Now\\nlengthen the exhalation by one more footstep.\\n\u2022\u2022 Watch to see whether the inhalation also lengthens by one step or not.\\n\u2022\u2022 Only lengthen the inhalation when you feel that it will be comfortable.\\n\u2022\u2022 After 20 breaths, return your breath to normal.\\n38.\\t\uf071\\tYour breath while listening to a piece of music.\\n\u2022\u2022 Breathe long, light, and even breaths.\\n\u2022\u2022 Follow your breath; be master of it, while remaining aware of the movement and\\nsentiments of the music.\\n\u2022\u2022 Do not get lost in the music, but continue to be master of your breath and yourself.\\n39.\\t\uf071\\tYour breath while listening to a friend\u2019s words and your own replies. Continue as with music.\\n40.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":80,\"book_page\":\"56\",\"text\":\"56\\nMindfulness Handout 4a (p. 3 of 4)\\nObserve thoughts coming in and out of your mind:\\n41. \uf071\\tNotice thoughts as they come into your mind.\\n\u2022\u2022 Ask, \u201cWhere do thoughts come from?\u201d\\n\u2022\u2022 Then watch them to see if you can see where they come into your mind.\\n42.\\t\uf071\\tAs you notice thoughts in your mind, notice the pauses between each thought.\\n43.\\t\uf071\\tImagine that your mind is the sky and that thoughts are clouds.\\n\u2022\u2022 Notice each thought-cloud as it drifts by, letting it drift in and out of your mind.\\n\u2022\u2022 Imagine thoughts as leaves on water flowing down a stream, as boats drifting by on the\\nlake, or as train cars rolling by you.\\n44.\\t\uf071\\tWhen worries go round and round in your mind, move your attention to the sensations\\nin your body (those most intense right now). Then, keeping your attention on your body\\nsensations, notice how long it takes for the worries to ooze away.\\n45.\\t\uf071\\tStep back from your mind, as if you are on top of a mountain and your mind is just a\\nboulder down below.\\n\u2022\u2022 Gaze at your mind, watching what thoughts come up when you are watching it.\\n\u2022\u2022 Come back into your mind before you stop.\\n46.\\t\uf071\\tWatch for the first two thoughts that come into your mind.\\n47. Other:\\nImagine that your mind is a:\\n48.\\t\uf071\\tConveyor belt, and that thoughts and feelings are coming down the belt.\\n\u2022\u2022 Put each thought or feeling in a box, and then put it on the conveyor belt and let it go by.\\n49.\\t\uf071\\tConveyor belt, and that you are sorting thoughts and feelings as they come down the belt.\\n\u2022\u2022 Label the types of thoughts or feelings coming by (e.g., worry thoughts, thoughts about\\nmy past, thoughts about my mother, planning-what-to-do thoughts, angry feeling, sad\\nfeelings).\\n\u2022\u2022 Put them in boxes nearby for another time.\\n50.\\t\uf071\\tRiver, and that thoughts and feelings are boats going down the river.\\n\u2022\u2022 Imagine sitting on the grass, watching the boats go by.\\n\u2022\u2022 Describe or label each boat as it goes by.\\n\u2022\u2022 Try not to jump on the boat.\\n51. \uf071\\tRailroad track, and that thoughts and feelings are train cars going by.\\n\u2022\u2022 Describe or label each as it goes by. Try not to jump on the train.\\n52.\\tOther:\\nObserve by expanding awareness:\\n53.\\t\uf071\\tBreathing in, notice your breath. Then, keeping your breath in your awareness, on the\\nnext breath notice your hands. Then, keeping both in your awareness, on the next breath\\nexpand your awareness to sounds.\\n\u2022\u2022 Continue holding all three in awareness at the same time.\\n\u2022\u2022 Practice this awareness of threes at other times, selecting other things to be aware of.\\n54.\\t\uf071\\tKeeping your focus on what you are currently doing, gently expand your awareness to\\ninclude the space around you.\\n55.\\t\uf071\\tGo hug a tree, and feel the sensations of the embrace.\\n\u2022\u2022 Attend to the embrace of the sheets and blankets or comforters around you as you lie in\\nbed.\\n\u2022\u2022 Do this when you feel lonely and want to be loved or to love.\\n56.\\tOther:\\n(continued on next page)\"},{\"pdf_page\":81,\"book_page\":\"57\",\"text\":\"57\\nMindfulness Handout 4a (p. 4 of 4)\\nOpen your mind to your senses:\\n57. \uf071\\tPractice walking with your senses as wide open as you can make them.\\n\u2022\u2022 Notice what you hear, see, and feel.\\n\u2022\u2022 Notice what you feel when shifting your weight between each step.\\n\u2022\u2022 Notice your body experience as you turn.\\n58.\\t\uf071\\tFor one mouthful in a meal, pause with a spoonful or forkful of food.\\n\u2022\u2022 Look at what you are going to eat, smell it, and listen to it. Then, when you are ready, put\\nit in your mouth.\\n\u2022\u2022 Note the taste, texture, temperature, and even the sound your teeth make in chewing your\\nmouthful slowly.\\n\u2022\u2022 Note the changes in its taste, texture, temperature, and sound as you chew it to\\ncompletion.\\n59.\\t\uf071\\tFocus your mind on paying attention to each sensation that comes into your mind.\\n\u2022\u2022 Attend to sensations of sight, smell, touch, hearing, and taste, or to the thoughts\\ngenerated by your brain.\\n\u2022\u2022 Notice sensations as they arise, and notice them as they fall away.\\n\u2022\u2022 Let your mind focus on each sensation as it arises.\\n\u2022\u2022 Notice each sensation with curiosity, allowing it to be. Examine the uniqueness of each\\nsensation.\\n60.\\t\uf071\\tBe here. Be in the present now.\\n\u2022\u2022 Take a moment to notice every sense you are aware of.\\n\u2022\u2022 To yourself, make a statement, about each sense: \u201cI feel the chair; the chair feels me.\u201d\\n\u201cI hear the heater; the heater hears me.\u201d \u201cI see the wall; the wall sees me.\u201d \u201cI hear a\\nstomach growl; it hears me.\u201d\\n61.\\t\uf071\\tWhen a feeling arises within you, notice it\u2014saying, for example, \u201cA feeling of sadness is\\narising within me.\u201d\\n62.\\t\uf071\\tWhen a thought arises within you, notice it\u2014saying, for example, \u201cThe thought \u2018It is hot in\\nhere\u2019 is arising within me.\u201d\\n63.\\t\uf071\\tTake just a moment of your time, and practice \u201cnothing-to-do\u201d mind.\\n\u2022\u2022 Let yourself become completely aware of your present experience, noticing sensations\\nand the space around you.\\n64.\\t\uf071\\tFind a small object, one you can hold in your hand. Place it in front of you on a table or in\\nyour lap. Observe it closely\u2014first not moving it, and then picking it up and turning it over\\nand around, gazing at it from different angles and in different lights. Just notice shapes,\\ncolors, sizes, and other characteristics that are visible.\\n\u2022\u2022 Then change your focus to your fingers and hands touching the object. Notice the\\nsensations of touching the object; notice the texture, temperature, and feel of the object.\\n\u2022\u2022 Put the object down. Close your eyes, and inhale and exhale deeply and slowly.\\n\u2022\u2022 Then, with beginner\u2019s mind, open your eyes. With new vision, once again notice the\\nobject. With beginner\u2019s mind, open to feeling new textures and sensations, explore the\\nobject with your fingers and hands.\\n\u2022\u2022 Put down the object, and once again focus your mind on inhaling and exhaling once.\\n65.\\tOther:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/02_DBT_Mindfulness/handouts/json/mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_your_senses_remember.json\",\"shared_output_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_y_91ad10e2.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"source_marker\":{\"_merged_values\":[\"Mindfulness Handout 4a   (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\",\"Mindfulness Handout 4a (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\"]},\"source_pdf_pages\":[78,79,80,81],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/mindfulness/handouts/mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_your_senses_remember.json\",\"item_number\":\"4a\",\"full_text\":{\"_merged_values\":[\"Mindfulness Handout 4a   (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\\nIdeas for Practicing Observing\\nBy Coming Back to Your Senses\\nRemember: Observing is bringing your mind back to the sensations of your body and mind.\\nObserve with your eyes:\\n  1.\\t\uf071\\tLie on the ground and watch the clouds in the sky.\\n  2.\\t\uf071\\tWalking slowly, stopping somewhere with a view, notice flowers, trees, and nature itself.\\n  3.\\t\uf071\\tSit outside. Watch who and what go by in front of you, without following them with your\\nhead or your eyes.\\n  4.\\t\uf071\\tNotice the facial expression and movements of another person. Refrain from labeling the\\nperson\u2019s emotions, thoughts, or interests.\\n  5.\\t\uf071\\tNotice just the eyes, lips, or hands of another person (or just one feature of an animal).\\n  6.\\t\uf071\\tPick up a leaf, a flower, or a pebble. Look at it closely, trying to see each detail.\\n  7.\\t \uf071\\tFind something beautiful to look at, and spend a few minutes contemplating it.\\n  8.\\tOther:\\nObserve sounds:\\n  9.\\t\uf071\\tStop for a moment and just listen. Listen to the texture and shape of the sounds around\\nyou. Listen to the silences between the sounds.\\n10.\\t\uf071\\tIf someone is talking, listen to the pitch of the voice, to the smoothness or roughness of the\\nsounds, to the clarity or the mumbling of the speech, to the pauses between the words.\\n11.\\t \uf071\\tListen to music, observing each note as it comes and the spaces between the notes. Try\\nbreathing the sounds into your body and letting them flow out again on your out breath.\\n12.\\tOther:\\nObserve smells around you:\\n13.\\t\uf071\\tBreathing in, notice any smells around you. Bring something close to your nose, and notice\\nthe smells. Take it away, and then notice the smells again. Do they linger?\\n14.\\t\uf071\\tWhen eating, notice the aroma of the food; when cooking, notice the aroma of the spices or\\nother ingredients; when bathing, smell the soap or shampoo; when walking outside, notice\\nthe aroma of the air; when near flowers, bend down and \u201csmell the roses.\u201d\\n15.\\tOther:\\nObserve taste and the act of eating:\\n16.\\t\uf071\\tPutting something in your mouth, pay attention to the taste. Keep it in your mouth, and\\nnotice all the taste sensations.\\n17.\\t \uf071\\tLick a lollipop or something else. Notice just the sensation of taste.\\n18.\\t\uf071\\tEat a meal, or even a part of a meal, paying attention to the taste of each mouthful.\\n19.\\tOther:\\nObserve urges to do something:\\nWhen you are feeling an urge to do something impulsive,\\n20.\\t\uf071\\t\u201cUrge-surf\u201d by imagining that your urges are a surfboard and you are standing on the\\nboard, riding the waves.\\n21.\\t\uf071\\tNotice any urge to avoid someone or something.\\n22.\\t\uf071\\tScan your entire body, and notice the sensations. Where in the body is the urge?\\n23.\\t\uf071\\tWhen you are chewing your food, notice when you have the urge to swallow.\\n24.\\tOther:\\n(continued on next page)\\n\\nMindfulness Handout 4a   (p. 2 of 4)\\nObserve sensations of touch on your skin:\\n25.\\t\uf071\\tStroke your upper lip with your fingernail.\\n\u2022\u2022 Stop stroking, and notice how long it takes before you can\u2019t sense your upper lip at all.\\n26.\\t\uf071\\tWhen walking, notice the sensations of walking\u2014your feet hitting the ground and rising up\\nand down. Sometimes walk very slowly and notice. Sometimes walk very fast and notice.\\n27.\\t \uf071\\tWhen sitting, notice your thighs on the chair. Notice the curve of your knees and your back.\\n28.\\t\uf071\\tPay attention to anything touching you.\\n\u2022\u2022 Try to feel your feet in your shoes, your body touching your clothes.\\n\u2022\u2022 Feel your arms touching a chair.\\n\u2022\u2022 Notice the sensations of your hands.\\n29.\\t\uf071\\tTouch something\u2014the wall, a fabric, a table top, a pet, a piece of fruit, a person.\\n\u2022\u2022 Notice the texture of what you feel, notice the sensations on your skin.\\n\u2022\u2022 Try it again with another part of your body.\\n\u2022\u2022 Notice the sensations again.\\n30.\\t\uf071\\tFocus your attention on the sensations in your chest, your stomach, or your shoulders.\\n31.\\t\uf071\\tFocus your attention on the place in your body where you feel tight or tense.\\n32.\\t\uf071\\tFocus your attention on the space between your eyes.\\n33.\\tOther:\\nObserve your breath: Breathe evenly and gently, focusing your attention on:\\n34.\\t\uf071\\tThe movement of your stomach.\\n\u2022\u2022 As you begin to breathe in, allow your belly to rise in order to bring air into the lower half\\nof your lungs.\\n\u2022\u2022 As the upper halves of your lungs begin to fill with air, your chest begins to rise.\\n\u2022\u2022 As you breathe out, notice your belly, then notice your chest. Don\u2019t tire yourself.\\n35.\\t\uf071\\tThe pauses in your breathing.\\n\u2022\u2022 As you breathe in, notice the brief pause when your lungs have filled with air.\\n\u2022\u2022 As you breathe out, notice the brief pause when you have expelled all the air.\\n36.\\t\uf071\\tThe sensations in your nose as you breathe in and as you breathe out.\\n\u2022\u2022 As you breathe, close your mouth and breathe in through your nose, noticing the\\nsensations traveling up and down your nostrils.\\n37.\\t \uf071\\tYour breath while walking slowly. Breathe normally.\\n\u2022\u2022 Determine the length of your breath\u2014the exhalation and the inhalation\u2014by the number\\nof your footsteps. Continue for a few minutes.\\n\u2022\u2022 Begin to lengthen your exhalation by one step. Do not force a longer inhalation. Let it be\\nnatural.\\n\u2022\u2022 Watch your inhalation carefully to see whether there is a desire to lengthen it. Now\\nlengthen the exhalation by one more footstep.\\n\u2022\u2022 Watch to see whether the inhalation also lengthens by one step or not.\\n\u2022\u2022 Only lengthen the inhalation when you feel that it will be comfortable.\\n\u2022\u2022 After 20 breaths, return your breath to normal.\\n38.\\t\uf071\\tYour breath while listening to a piece of music.\\n\u2022\u2022 Breathe long, light, and even breaths.\\n\u2022\u2022 Follow your breath; be master of it, while remaining aware of the movement and\\nsentiments of the music.\\n\u2022\u2022 Do not get lost in the music, but continue to be master of your breath and yourself.\\n39.\\t\uf071\\tYour breath while listening to a friend\u2019s words and your own replies. Continue as with music.\\n40.\\tOther:\\n(continued on next page)\\n\\nMindfulness Handout 4a   (p. 3 of 4)\\nObserve thoughts coming in and out of your mind:\\n41.\\t \uf071\\tNotice thoughts as they come into your mind.\\n\u2022\u2022 Ask, \u201cWhere do thoughts come from?\u201d\\n\u2022\u2022 Then watch them to see if you can see where they come into your mind.\\n42.\\t\uf071\\tAs you notice thoughts in your mind, notice the pauses between each thought.\\n43.\\t\uf071\\tImagine that your mind is the sky and that thoughts are clouds.\\n\u2022\u2022 Notice each thought-cloud as it drifts by, letting it drift in and out of your mind.\\n\u2022\u2022 Imagine thoughts as leaves on water flowing down a stream, as boats drifting by on the\\nlake, or as train cars rolling by you.\\n44.\\t\uf071\\tWhen worries go round and round in your mind, move your attention to the sensations\\nin your body (those most intense right now). Then, keeping your attention on your body\\nsensations, notice how long it takes for the worries to ooze away.\\n45.\\t\uf071\\tStep back from your mind, as if you are on top of a mountain and your mind is just a\\nboulder down below.\\n\u2022\u2022 Gaze at your mind, watching what thoughts come up when you are watching it.\\n\u2022\u2022 Come back into your mind before you stop.\\n46.\\t\uf071\\tWatch for the first two thoughts that come into your mind.\\n47.\\t Other:\\nImagine that your mind is a:\\n48.\\t\uf071\\tConveyor belt, and that thoughts and feelings are coming down the belt.\\n\u2022\u2022 Put each thought or feeling in a box, and then put it on the conveyor belt and let it go by.\\n49.\\t\uf071\\tConveyor belt, and that you are sorting thoughts and feelings as they come down the belt.\\n\u2022\u2022 Label the types of thoughts or feelings coming by (e.g., worry thoughts, thoughts about\\nmy past, thoughts about my mother, planning-what-to-do thoughts, angry feeling, sad\\nfeelings).\\n\u2022\u2022 Put them in boxes nearby for another time.\\n50.\\t\uf071\\tRiver, and that thoughts and feelings are boats going down the river.\\n\u2022\u2022 Imagine sitting on the grass, watching the boats go by.\\n\u2022\u2022 Describe or label each boat as it goes by.\\n\u2022\u2022 Try not to jump on the boat.\\n51.\\t \uf071\\tRailroad track, and that thoughts and feelings are train cars going by.\\n\u2022\u2022 Describe or label each as it goes by. Try not to jump on the train.\\n52.\\tOther:\\nObserve by expanding awareness:\\n53.\\t\uf071\\tBreathing in, notice your breath. Then, keeping your breath in your awareness, on the\\nnext breath notice your hands. Then, keeping both in your awareness, on the next breath\\nexpand your awareness to sounds.\\n\u2022\u2022 Continue holding all three in awareness at the same time.\\n\u2022\u2022 Practice this awareness of threes at other times, selecting other things to be aware of.\\n54.\\t\uf071\\tKeeping your focus on what you are currently doing, gently expand your awareness to\\ninclude the space around you.\\n55.\\t\uf071\\tGo hug a tree, and feel the sensations of the embrace.\\n\u2022\u2022 Attend to the embrace of the sheets and blankets or comforters around you as you lie in\\nbed.\\n\u2022\u2022 Do this when you feel lonely and want to be loved or to love.\\n56.\\tOther:\\n(continued on next page)\\n\\nMindfulness Handout 4a   (p. 4 of 4)\\nOpen your mind to your senses:\\n57.\\t \uf071\\tPractice walking with your senses as wide open as you can make them.\\n\u2022\u2022 Notice what you hear, see, and feel.\\n\u2022\u2022 Notice what you feel when shifting your weight between each step.\\n\u2022\u2022 Notice your body experience as you turn.\\n58.\\t\uf071\\tFor one mouthful in a meal, pause with a spoonful or forkful of food.\\n\u2022\u2022 Look at what you are going to eat, smell it, and listen to it. Then, when you are ready, put\\nit in your mouth.\\n\u2022\u2022 Note the taste, texture, temperature, and even the sound your teeth make in chewing your\\nmouthful slowly.\\n\u2022\u2022 Note the changes in its taste, texture, temperature, and sound as you chew it to\\ncompletion.\\n59.\\t\uf071\\tFocus your mind on paying attention to each sensation that comes into your mind.\\n\u2022\u2022 Attend to sensations of sight, smell, touch, hearing, and taste, or to the thoughts\\ngenerated by your brain.\\n\u2022\u2022 Notice sensations as they arise, and notice them as they fall away.\\n\u2022\u2022 Let your mind focus on each sensation as it arises.\\n\u2022\u2022 Notice each sensation with curiosity, allowing it to be. Examine the uniqueness of each\\nsensation.\\n60.\\t\uf071\\tBe here. Be in the present now.\\n\u2022\u2022 Take a moment to notice every sense you are aware of.\\n\u2022\u2022 To yourself, make a statement, about each sense: \u201cI feel the chair; the chair feels me.\u201d\\n\u201cI hear the heater; the heater hears me.\u201d \u201cI see the wall; the wall sees me.\u201d \u201cI hear a\\nstomach growl; it hears me.\u201d\\n61.\\t\uf071\\tWhen a feeling arises within you, notice it\u2014saying, for example, \u201cA feeling of sadness is\\narising within me.\u201d\\n62.\\t\uf071\\tWhen a thought arises within you, notice it\u2014saying, for example, \u201cThe thought \u2018It is hot in\\nhere\u2019 is arising within me.\u201d\\n63.\\t\uf071\\tTake just a moment of your time, and practice \u201cnothing-to-do\u201d mind.\\n\u2022\u2022 Let yourself become completely aware of your present experience, noticing sensations\\nand the space around you.\\n64.\\t\uf071\\tFind a small object, one you can hold in your hand. Place it in front of you on a table or in\\nyour lap. Observe it closely\u2014first not moving it, and then picking it up and turning it over\\nand around, gazing at it from different angles and in different lights. Just notice shapes,\\ncolors, sizes, and other characteristics that are visible.\\n\u2022\u2022 Then change your focus to your fingers and hands touching the object. Notice the\\nsensations of touching the object; notice the texture, temperature, and feel of the object.\\n\u2022\u2022 Put the object down. Close your eyes, and inhale and exhale deeply and slowly.\\n\u2022\u2022 Then, with beginner\u2019s mind, open your eyes. With new vision, once again notice the\\nobject. With beginner\u2019s mind, open to feeling new textures and sensations, explore the\\nobject with your fingers and hands.\\n\u2022\u2022 Put down the object, and once again focus your mind on inhaling and exhaling once.\\n65.\\tOther:\",\"Mindfulness Handout 4a (Mindfulness Worksheets 2\u20132c, 4\u20134b) (p. 1 of 4)\\nIdeas for Practicing Observing\\nBy Coming Back to Your Senses\\nRemember: Observing is bringing your mind back to the sensations of your body and mind.\\nObserve with your eyes: 1.\\t\uf071\\tLie on the ground and watch the clouds in the sky. 2.\\t\uf071\\tWalking slowly, stopping somewhere with a view, notice flowers, trees, and nature itself. 3.\\t\uf071\\tSit outside. Watch who and what go by in front of you, without following them with your\\nhead or your eyes. 4.\\t\uf071\\tNotice the facial expression and movements of another person. Refrain from labeling the\\nperson\u2019s emotions, thoughts, or interests. 5.\\t\uf071\\tNotice just the eyes, lips, or hands of another person (or just one feature of an animal). 6.\\t\uf071\\tPick up a leaf, a flower, or a pebble. Look at it closely, trying to see each detail. 7. \uf071\\tFind something beautiful to look at, and spend a few minutes contemplating it. 8.\\tOther:\\nObserve sounds: 9.\\t\uf071\\tStop for a moment and just listen. Listen to the texture and shape of the sounds around\\nyou. Listen to the silences between the sounds.\\n10.\\t\uf071\\tIf someone is talking, listen to the pitch of the voice, to the smoothness or roughness of the\\nsounds, to the clarity or the mumbling of the speech, to the pauses between the words.\\n11. \uf071\\tListen to music, observing each note as it comes and the spaces between the notes. Try\\nbreathing the sounds into your body and letting them flow out again on your out breath.\\n12.\\tOther:\\nObserve smells around you:\\n13.\\t\uf071\\tBreathing in, notice any smells around you. Bring something close to your nose, and notice\\nthe smells. Take it away, and then notice the smells again. Do they linger?\\n14.\\t\uf071\\tWhen eating, notice the aroma of the food; when cooking, notice the aroma of the spices or\\nother ingredients; when bathing, smell the soap or shampoo; when walking outside, notice\\nthe aroma of the air; when near flowers, bend down and \u201csmell the roses.\u201d\\n15.\\tOther:\\nObserve taste and the act of eating:\\n16.\\t\uf071\\tPutting something in your mouth, pay attention to the taste. Keep it in your mouth, and\\nnotice all the taste sensations.\\n17. \uf071\\tLick a lollipop or something else. Notice just the sensation of taste.\\n18.\\t\uf071\\tEat a meal, or even a part of a meal, paying attention to the taste of each mouthful.\\n19.\\tOther:\\nObserve urges to do something:\\nWhen you are feeling an urge to do something impulsive,\\n20.\\t\uf071\\t\u201cUrge-surf\u201d by imagining that your urges are a surfboard and you are standing on the\\nboard, riding the waves.\\n21.\\t\uf071\\tNotice any urge to avoid someone or something.\\n22.\\t\uf071\\tScan your entire body, and notice the sensations. Where in the body is the urge?\\n23.\\t\uf071\\tWhen you are chewing your food, notice when you have the urge to swallow.\\n24.\\tOther:\\n(continued on next page) Mindfulness Handout 4a (p. 2 of 4)\\nObserve sensations of touch on your skin:\\n25.\\t\uf071\\tStroke your upper lip with your fingernail.\\n\u2022\u2022 Stop stroking, and notice how long it takes before you can\u2019t sense your upper lip at all.\\n26.\\t\uf071\\tWhen walking, notice the sensations of walking\u2014your feet hitting the ground and rising up\\nand down. Sometimes walk very slowly and notice. Sometimes walk very fast and notice.\\n27. \uf071\\tWhen sitting, notice your thighs on the chair. Notice the curve of your knees and your back.\\n28.\\t\uf071\\tPay attention to anything touching you.\\n\u2022\u2022 Try to feel your feet in your shoes, your body touching your clothes.\\n\u2022\u2022 Feel your arms touching a chair.\\n\u2022\u2022 Notice the sensations of your hands.\\n29.\\t\uf071\\tTouch something\u2014the wall, a fabric, a table top, a pet, a piece of fruit, a person.\\n\u2022\u2022 Notice the texture of what you feel, notice the sensations on your skin.\\n\u2022\u2022 Try it again with another part of your body.\\n\u2022\u2022 Notice the sensations again.\\n30.\\t\uf071\\tFocus your attention on the sensations in your chest, your stomach, or your shoulders.\\n31.\\t\uf071\\tFocus your attention on the place in your body where you feel tight or tense.\\n32.\\t\uf071\\tFocus your attention on the space between your eyes.\\n33.\\tOther:\\nObserve your breath: Breathe evenly and gently, focusing your attention on:\\n34.\\t\uf071\\tThe movement of your stomach.\\n\u2022\u2022 As you begin to breathe in, allow your belly to rise in order to bring air into the lower half\\nof your lungs.\\n\u2022\u2022 As the upper halves of your lungs begin to fill with air, your chest begins to rise.\\n\u2022\u2022 As you breathe out, notice your belly, then notice your chest. Don\u2019t tire yourself.\\n35.\\t\uf071\\tThe pauses in your breathing.\\n\u2022\u2022 As you breathe in, notice the brief pause when your lungs have filled with air.\\n\u2022\u2022 As you breathe out, notice the brief pause when you have expelled all the air.\\n36.\\t\uf071\\tThe sensations in your nose as you breathe in and as you breathe out.\\n\u2022\u2022 As you breathe, close your mouth and breathe in through your nose, noticing the\\nsensations traveling up and down your nostrils.\\n37. \uf071\\tYour breath while walking slowly. Breathe normally.\\n\u2022\u2022 Determine the length of your breath\u2014the exhalation and the inhalation\u2014by the number\\nof your footsteps. Continue for a few minutes.\\n\u2022\u2022 Begin to lengthen your exhalation by one step. Do not force a longer inhalation. Let it be\\nnatural.\\n\u2022\u2022 Watch your inhalation carefully to see whether there is a desire to lengthen it. Now\\nlengthen the exhalation by one more footstep.\\n\u2022\u2022 Watch to see whether the inhalation also lengthens by one step or not.\\n\u2022\u2022 Only lengthen the inhalation when you feel that it will be comfortable.\\n\u2022\u2022 After 20 breaths, return your breath to normal.\\n38.\\t\uf071\\tYour breath while listening to a piece of music.\\n\u2022\u2022 Breathe long, light, and even breaths.\\n\u2022\u2022 Follow your breath; be master of it, while remaining aware of the movement and\\nsentiments of the music.\\n\u2022\u2022 Do not get lost in the music, but continue to be master of your breath and yourself.\\n39.\\t\uf071\\tYour breath while listening to a friend\u2019s words and your own replies. Continue as with music.\\n40.\\tOther:\\n(continued on next page) Mindfulness Handout 4a (p. 3 of 4)\\nObserve thoughts coming in and out of your mind:\\n41. \uf071\\tNotice thoughts as they come into your mind.\\n\u2022\u2022 Ask, \u201cWhere do thoughts come from?\u201d\\n\u2022\u2022 Then watch them to see if you can see where they come into your mind.\\n42.\\t\uf071\\tAs you notice thoughts in your mind, notice the pauses between each thought.\\n43.\\t\uf071\\tImagine that your mind is the sky and that thoughts are clouds.\\n\u2022\u2022 Notice each thought-cloud as it drifts by, letting it drift in and out of your mind.\\n\u2022\u2022 Imagine thoughts as leaves on water flowing down a stream, as boats drifting by on the\\nlake, or as train cars rolling by you.\\n44.\\t\uf071\\tWhen worries go round and round in your mind, move your attention to the sensations\\nin your body (those most intense right now). Then, keeping your attention on your body\\nsensations, notice how long it takes for the worries to ooze away.\\n45.\\t\uf071\\tStep back from your mind, as if you are on top of a mountain and your mind is just a\\nboulder down below.\\n\u2022\u2022 Gaze at your mind, watching what thoughts come up when you are watching it.\\n\u2022\u2022 Come back into your mind before you stop.\\n46.\\t\uf071\\tWatch for the first two thoughts that come into your mind.\\n47. Other:\\nImagine that your mind is a:\\n48.\\t\uf071\\tConveyor belt, and that thoughts and feelings are coming down the belt.\\n\u2022\u2022 Put each thought or feeling in a box, and then put it on the conveyor belt and let it go by.\\n49.\\t\uf071\\tConveyor belt, and that you are sorting thoughts and feelings as they come down the belt.\\n\u2022\u2022 Label the types of thoughts or feelings coming by (e.g., worry thoughts, thoughts about\\nmy past, thoughts about my mother, planning-what-to-do thoughts, angry feeling, sad\\nfeelings).\\n\u2022\u2022 Put them in boxes nearby for another time.\\n50.\\t\uf071\\tRiver, and that thoughts and feelings are boats going down the river.\\n\u2022\u2022 Imagine sitting on the grass, watching the boats go by.\\n\u2022\u2022 Describe or label each boat as it goes by.\\n\u2022\u2022 Try not to jump on the boat.\\n51. \uf071\\tRailroad track, and that thoughts and feelings are train cars going by.\\n\u2022\u2022 Describe or label each as it goes by. Try not to jump on the train.\\n52.\\tOther:\\nObserve by expanding awareness:\\n53.\\t\uf071\\tBreathing in, notice your breath. Then, keeping your breath in your awareness, on the\\nnext breath notice your hands. Then, keeping both in your awareness, on the next breath\\nexpand your awareness to sounds.\\n\u2022\u2022 Continue holding all three in awareness at the same time.\\n\u2022\u2022 Practice this awareness of threes at other times, selecting other things to be aware of.\\n54.\\t\uf071\\tKeeping your focus on what you are currently doing, gently expand your awareness to\\ninclude the space around you.\\n55.\\t\uf071\\tGo hug a tree, and feel the sensations of the embrace.\\n\u2022\u2022 Attend to the embrace of the sheets and blankets or comforters around you as you lie in\\nbed.\\n\u2022\u2022 Do this when you feel lonely and want to be loved or to love.\\n56.\\tOther:\\n(continued on next page) Mindfulness Handout 4a (p. 4 of 4)\\nOpen your mind to your senses:\\n57. \uf071\\tPractice walking with your senses as wide open as you can make them.\\n\u2022\u2022 Notice what you hear, see, and feel.\\n\u2022\u2022 Notice what you feel when shifting your weight between each step.\\n\u2022\u2022 Notice your body experience as you turn.\\n58.\\t\uf071\\tFor one mouthful in a meal, pause with a spoonful or forkful of food.\\n\u2022\u2022 Look at what you are going to eat, smell it, and listen to it. Then, when you are ready, put\\nit in your mouth.\\n\u2022\u2022 Note the taste, texture, temperature, and even the sound your teeth make in chewing your\\nmouthful slowly.\\n\u2022\u2022 Note the changes in its taste, texture, temperature, and sound as you chew it to\\ncompletion.\\n59.\\t\uf071\\tFocus your mind on paying attention to each sensation that comes into your mind.\\n\u2022\u2022 Attend to sensations of sight, smell, touch, hearing, and taste, or to the thoughts\\ngenerated by your brain.\\n\u2022\u2022 Notice sensations as they arise, and notice them as they fall away.\\n\u2022\u2022 Let your mind focus on each sensation as it arises.\\n\u2022\u2022 Notice each sensation with curiosity, allowing it to be. Examine the uniqueness of each\\nsensation.\\n60.\\t\uf071\\tBe here. Be in the present now.\\n\u2022\u2022 Take a moment to notice every sense you are aware of.\\n\u2022\u2022 To yourself, make a statement, about each sense: \u201cI feel the chair; the chair feels me.\u201d\\n\u201cI hear the heater; the heater hears me.\u201d \u201cI see the wall; the wall sees me.\u201d \u201cI hear a\\nstomach growl; it hears me.\u201d\\n61.\\t\uf071\\tWhen a feeling arises within you, notice it\u2014saying, for example, \u201cA feeling of sadness is\\narising within me.\u201d\\n62.\\t\uf071\\tWhen a thought arises within you, notice it\u2014saying, for example, \u201cThe thought \u2018It is hot in\\nhere\u2019 is arising within me.\u201d\\n63.\\t\uf071\\tTake just a moment of your time, and practice \u201cnothing-to-do\u201d mind.\\n\u2022\u2022 Let yourself become completely aware of your present experience, noticing sensations\\nand the space around you.\\n64.\\t\uf071\\tFind a small object, one you can hold in your hand. Place it in front of you on a table or in\\nyour lap. Observe it closely\u2014first not moving it, and then picking it up and turning it over\\nand around, gazing at it from different angles and in different lights. Just notice shapes,\\ncolors, sizes, and other characteristics that are visible.\\n\u2022\u2022 Then change your focus to your fingers and hands touching the object. Notice the\\nsensations of touching the object; notice the texture, temperature, and feel of the object.\\n\u2022\u2022 Put the object down. Close your eyes, and inhale and exhale deeply and slowly.\\n\u2022\u2022 Then, with beginner\u2019s mind, open your eyes. With new vision, once again notice the\\nobject. With beginner\u2019s mind, open to feeling new textures and sensations, explore the\\nobject with your fingers and hands.\\n\u2022\u2022 Put down the object, and once again focus your mind on inhaling and exhaling once.\\n65.\\tOther:\"]},\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Mindfulness Worksheets 2\u20132c, 4\u20134b\"],\"ourspace_kindness_pass\":{\"schema_name\":\"ourspace_dbt_adhd_kindness_pass\",\"schema_version\":\"1.0.0\",\"generated_at_utc\":\"2026-06-25T21:00:29.329839+00:00\",\"shared_library\":true,\"routine_cadence\":\"daily\",\"source_relative_path\":\"02_DBT_Mindfulness/handouts/json/mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_your_senses_remember.json\",\"title\":\"Ideas for Practicing Observing By Coming Back to Your Senses Remember: Observing is bringing your mind back to the sensations of your body and mind. Observe with your eyes:\",\"category\":\"DBT Mindfulness\",\"source_type\":\"handout\",\"disability_profile_basis\":{\"william\":{\"main_doability_needs\":[\"bed-level or seated options by default\",\"oxygen/breathing, pain, vertigo, fatigue, mobility, and recovery time respected\",\"ADHD/autism supports: transitions, low-stimulation starts, tiny visible steps\",\"partial completion and stopping before a crash count as success\",\"no shame, no body blame, no pressure to push through pain or dysphoria\"],\"care_language\":\"direct, validating, masculine, autonomy-preserving, privacy-respecting\"},\"jasper\":{\"main_doability_needs\":[\"ADHD transition support before task demands\",\"caregiver burnout recovery treated as care, not avoidance\",\"protected rest, boundaries, decompression, sensory needs, and people-pleasing checks\",\"low-energy, one-field, one-minute versions allowed\",\"no assumption that Jasper has unlimited caregiver capacity\"],\"care_language\":\"they/them, body-neutral, consent-based, non-shaming, burnout-aware\"},\"shared\":{\"household_rules\":[\"no hour block may hold more than two tasks/tools\",\"skills may be used as one-breath or one-field versions\",\"survival days load critical care first and skip optional worksheets\",\"rest, boundaries, decompression, and asking for help count as care\",\"skills are for support, not grades\"]}},\"universal_kindness_rules\":[\"This is a support tool, not a test.\",\"One line, one checkbox, one breath, or one tiny step counts.\",\"Skipping a skill because the body is unsafe, exhausted, dysregulated, or overloaded is allowed.\",\"Do not stack this with more than one other task inside the same hour.\",\"Survival-day version always wins over perfection.\"],\"william_accessibility_adaptations\":[\"Use bed-level, seated, voice-note, or caregiver-assisted versions when needed.\",\"Avoid pain escalation, respiratory strain, unsafe transfers, and dysphoria-triggering language.\",\"Break worksheets into one-field chunks; stopping before a crash is success.\"],\"jasper_accessibility_adaptations\":[\"Start with transition support before expecting focus.\",\"Protect caregiver burnout recovery; rest and boundaries are valid completion.\",\"Use body-doubling, timers, low-stimulation versions, and one-minute starts.\"],\"tiny_steps\":[\"Take one breath.\",\"Name one body sensation or one fact.\",\"Choose one kind next step or stop for rest.\"],\"routine_integration\":{\"routine_role\":\"small daily support option\",\"start_the_day_use\":\"eligible as a rotating daily skill, never more than one DBT/ADHD skill in an hour block\",\"recommended_block\":\"after body check or before decompression\"},\"completion_rules\":{\"partial_completion_counts\":true,\"can_be_paused_and_resumed\":true,\"no_shame_if_skipped\":true,\"low_spoon_version_required\":true,\"can_be_done_separately_by_william_and_jasper\":true,\"can_be_done_together_only_if_both_people_have_capacity\":true},\"schedule_policy\":{\"start_the_day_eligible\":true,\"expanded_day_eligible\":true,\"max_items_per_hour_block\":2,\"do_not_force_into_day\":false,\"do_not_stack_with\":[\"appointment\",\"heavy_chore\",\"conflict_repair\",\"hygiene_overload\",\"caregiver_overload\"]},\"currency_suggestion\":{\"platinum\":0,\"gold\":0,\"silver\":3,\"copper\":0}},\"id\":{\"_merged_values\":[\"mindfulness_handout_4a\",\"mindfulness-handout-4a\"]},\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Ideas for Practicing Observing By Coming Back to Your Senses Remember: Observing is bringing your mind back to the sensations of your body and mind. Observe with your eyes:\",\"domain\":\"mindfulness\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Mindfulness is allowed to be tiny, sensory-safe, and done from bed or wheelchair. Noticing without judging counts even when the day is messy.\",\"tiny_steps\":[\"Notice one body signal.\",\"Name one feeling or need.\",\"Find one neutral thing in the room.\",\"Return to the next safe action.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Use eyes-open grounding if closing eyes feels unsafe.\",\"Use quiet, low-scent, low-touch options for MCAS, trauma, and sensory overload.\",\"No posture requirement; lying down or supported sitting is valid.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not force stillness when it increases pain, panic, dysphoria, or trauma activation.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"mindfulness\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"54\",\"55\",\"56\",\"57\"],\"title\":\"Ideas for Practicing Observing By Coming Back to Your Senses Remember: Observing is bringing your mind back to the sensations of your body and mind. Observe with your eyes:\",\"module_category\":\"Mindfulness Skills\",\"shared_json_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_4a_ideas_for_practicing_observing_by_coming_back_to_y_91ad10e2.json\",\"module\":\"Mindfulness\",\"keywords\":[\"Back\",\"Coming\",\"Ideas\",\"Observe\",\"Observing\",\"Practicing\",\"Remember\",\"Senses\",\"Your\",\"back\",\"body\",\"bringing\",\"eyes\",\"mind\",\"sensations\",\"with\",\"your\"]}}");
